use verus::prelude::*;

#[verus::verifier::verus]   // turn on the Verus verifier
#[requires(n >= 0 && n <= 127)]
#[ensures(
    // There exists a non‐negative tuple (c0,…,c4) of coin counts
    // summing to n, and ret is exactly their total.
    exists(|c0: i8, c1: i8, c2: i8, c3: i8, c4: i8| {
        n == 100*c0 + 20*c1 + 10*c2 + 5*c3 + 1*c4
        &&  ret == c0 + c1 + c2 + c3 + c4
        &&  c0 >= 0 && c1 >= 0 && c2 >= 0 && c3 >= 0 && c4 >= 0
    })
)]
#[ensures(
    // And for _any_ non‐negative decomposition (d0,…,d4) of n,
    // our ret is no greater than their total.  Hence minimality.
    forall(|d0: i8, d1: i8, d2: i8, d3: i8, d4: i8| {
        d0 >= 0 && d1 >= 0 && d2 >= 0 && d3 >= 0 && d4 >= 0
        && n == 100*d0 + 20*d1 + 10*d2 + 5*d3 + 1*d4
        ==> ret <= d0 + d1 + d2 + d3 + d4
    })
)]
fn solve(n: i8) -> i8 {
    let mut remaining = n;
    let mut count: i8 = 0;
    for &denom in &[100_i8, 20, 10, 5, 1] {
        // greedy step
        count += remaining / denom;
        remaining %= denom;
    }
    count
}

